import java.util.*;class Solution{public int maxSumSubmatrix(int[][]a,int k){int m=a.length,n=a[0].length,b=Integer.MIN_VALUE;for(int top=0;top<m;top++){int[]s=new int[n];for(int bot=top;bot<m;bot++){for(int c=0;c<n;c++)s[c]+=a[bot][c];TreeSet<Integer>p=new TreeSet<>();p.add(0);int cur=0;for(int x:s){cur+=x;Integer v=p.ceiling(cur-k);if(v!=null)b=Math.max(b,cur-v);p.add(cur);}}}return b;}}
